#!/usr/bin/env python3
# ============================================================================
#  Grand Theft Auto VI - "Setup"   (harmless April-fools style prank)
# ----------------------------------------------------------------------------
#  Runs on Windows, macOS and Linux.  Needs only Python 3 with tkinter
#  (bundled with the standard python.org installers on Win/Mac).
#
#  It installs NOTHING and writes nothing permanent to disk.  It shows a fake
#  setup wizard; the progress bar stalls at 66%, then a full-screen image pops
#  up with "FOOLS!", a surprise sound plays and a voice says "Fools!".
#  Press Esc or click to close.
# ============================================================================
import sys, os, random, tempfile, subprocess, base64
import tkinter as tk
from tkinter import ttk

GORILLA_B64 = ""
BANNER_B64  = ""
SOUND_B64   = ""

FILES = ["vice_city_map.pak", "leonida_keys.pak", "lucia_anim.bin", "jason_voice.wem",
         "vehicles_hd.pak", "police_ai.dll", "radio_vicecity_fm.ogg", "flamingo_physics.bin",
         "textures_8k_part1.pak", "textures_8k_part2.pak", "alligators.dat", "beach_npcs.bin",
         "online_shark_cards.cfg", "weather_hurricane.fx", "shaders_rt.cache"]

_tmp = []
def _dump(b64, suffix):
    fd, path = tempfile.mkstemp(suffix=suffix)
    os.write(fd, base64.b64decode(b64)); os.close(fd)
    _tmp.append(path); return path

def play_sound():
    try:
        path = _dump(SOUND_B64, ".wav")
        if sys.platform.startswith("win"):
            import winsound
            winsound.PlaySound(path, winsound.SND_FILENAME | winsound.SND_ASYNC)
        elif sys.platform == "darwin":
            subprocess.Popen(["afplay", path])
        else:
            for player in (["paplay", path], ["aplay", "-q", path], ["ffplay", "-nodisp", "-autoexit", path]):
                try:
                    subprocess.Popen(player, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); break
                except FileNotFoundError:
                    continue
    except Exception:
        pass

def speak(text):
    try:
        if sys.platform.startswith("win"):
            ps = ("Add-Type -AssemblyName System.Speech;"
                  "$s=New-Object System.Speech.Synthesis.SpeechSynthesizer;"
                  "$s.Rate=-1;$s.Volume=100;$s.Speak('%s')" % text)
            subprocess.Popen(["powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command", ps],
                             creationflags=0x08000000)
        elif sys.platform == "darwin":
            subprocess.Popen(["say", "-r", "150", text])
        else:
            subprocess.Popen(["espeak", text], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass

def cleanup():
    for p in _tmp:
        try: os.remove(p)
        except Exception: pass


class Setup(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Grand Theft Auto VI - Setup")
        self.geometry("640x470"); self.resizable(False, False)
        self.configure(bg="#14091f")
        try:
            self.banner = tk.PhotoImage(data=BANNER_B64)
            tk.Label(self, image=self.banner, bd=0).pack()
        except Exception:
            tk.Label(self, text="GRAND THEFT AUTO VI", fg="#ff4fa8", bg="#14091f",
                     font=("Arial", 26, "bold"), pady=28).pack(fill="x")
        self.gorilla = tk.PhotoImage(data=GORILLA_B64)
        self.body = tk.Frame(self, bg="#14091f"); self.body.pack(fill="both", expand=True, padx=28, pady=16)
        st = ttk.Style(self)
        try: st.theme_use("clam")
        except Exception: pass
        st.configure("G.Horizontal.TProgressbar", troughcolor="#2a1640", background="#ff4fa8",
                     bordercolor="#2a1640", lightcolor="#ff7cc0", darkcolor="#e0358a", thickness=22)
        self.welcome()

    def clear(self):
        for w in self.body.winfo_children(): w.destroy()

    def btn(self, text, cmd):
        return tk.Button(self.body, text=text, command=cmd, bg="#ff4fa8", fg="white",
                         activebackground="#ff7cc0", activeforeground="white",
                         font=("Segoe UI", 11, "bold"), relief="flat", padx=26, pady=6,
                         cursor="hand2", highlightthickness=0, bd=0)

    def welcome(self):
        self.clear()
        tk.Label(self.body, text="Welcome to Grand Theft Auto VI Setup", fg="white", bg="#14091f",
                 font=("Segoe UI", 15, "bold")).pack(anchor="w")
        tk.Label(self.body, justify="left", fg="#c9b8e0", bg="#14091f", font=("Segoe UI", 10),
                 text="Version 1.0.19   |   Download size: 1 MB   |   Install size: 1 MB\n\n"
                      "Setup will install Grand Theft Auto VI on your computer.\n"
                      "It is recommended that you close all other applications before continuing."
                 ).pack(anchor="w", pady=(8, 0))
        self.agree = tk.IntVar(value=1)
        tk.Checkbutton(self.body, text="I accept the License Agreement", variable=self.agree,
                       fg="white", bg="#14091f", selectcolor="#2a1640", activebackground="#14091f",
                       activeforeground="white", font=("Segoe UI", 10)).pack(anchor="w", pady=10)
        self.btn("Install", self.install).pack(anchor="e", side="bottom")

    def install(self):
        self.clear()
        tk.Label(self.body, text="Installing...", fg="white", bg="#14091f",
                 font=("Segoe UI", 15, "bold")).pack(anchor="w")
        self.status = tk.Label(self.body, text="", fg="#c9b8e0", bg="#14091f",
                               font=("Consolas", 10), anchor="w")
        self.status.pack(fill="x", pady=(10, 4))
        self.bar = ttk.Progressbar(self.body, style="G.Horizontal.TProgressbar", maximum=100, length=580)
        self.bar.pack(fill="x")
        self.pct = tk.Label(self.body, text="0%", fg="white", bg="#14091f", font=("Segoe UI", 10, "bold"))
        self.pct.pack(anchor="e", pady=4)
        self.p = 0.0; self.tick()

    def tick(self):
        self.p += random.uniform(0.15, 1.1) * (0.3 if 55 < self.p < 66 else 1)
        if self.p >= 66:
            self.p = 66; self.bar["value"] = 66; self.pct.config(text="66%"); self.show(); return
        self.bar["value"] = self.p
        self.pct.config(text=f"{int(self.p)}%")
        f = FILES[int(self.p / 66 * len(FILES)) % len(FILES)]
        self.status.config(text=f"Extracting: C:\\Games\\GTA VI\\data\\{f}")
        self.after(random.randint(45, 150), self.tick)

    def show(self):
        top = tk.Toplevel(self)
        top.geometry(f"{self.winfo_screenwidth()}x{self.winfo_screenheight()}+0+0")
        top.attributes("-topmost", True)
        try: top.attributes("-fullscreen", True)
        except Exception: pass
        top.configure(bg="black")
        c = tk.Canvas(top, bg="black", highlightthickness=0); c.pack(fill="both", expand=True)
        top.update_idletasks()
        w, h = top.winfo_screenwidth(), top.winfo_screenheight()
        gh = self.gorilla.height()
        img = c.create_image(w // 2, int(h * 0.42), image=self.gorilla)
        txt = c.create_text(w // 2, int(h * 0.42) + gh // 2 + 70,
                            text="FOOLS!", fill="#ff2d6f", font=("Impact", 96, "bold"))
        c.create_text(w // 2, h - 34, text="GTA VI is not out.   Press  Esc  to close.",
                      fill="#888", font=("Segoe UI", 13))
        play_sound(); speak("Fools!")
        state = {"n": 0}
        def anim():
            if not top.winfo_exists(): return
            n = state["n"]; state["n"] += 1
            dx, dy = (random.randint(-12, 12), random.randint(-12, 12)) if n < 22 else (0, 0)
            c.coords(img, w // 2 + dx, int(h * 0.42) + dy)
            c.itemconfig(txt, fill="#ff2d6f" if n % 6 < 3 else "#ffd23f")
            top.after(45, anim)
        anim()
        def close(e=None): cleanup(); self.destroy()
        for seq in ("<Escape>", "<Button-1>", "<Key>"): top.bind(seq, close)
        top.protocol("WM_DELETE_WINDOW", close); top.focus_force()


if __name__ == "__main__":
    try:
        Setup().mainloop()
    finally:
        cleanup()
